                <Button variant="secondary" className="w-full justify-center mt-2 text-xs" disabled={busy} onClick={() => decide(true, true)}>
                    知悉仍有 {openCount} 条未关闭意见，仍确认资格
                </Button>
            )}
        </Card>
    );
}

